function Wallet(owner, cents) {
  this.owner = owner;
  this.cents = cents;
}

Wallet.prototype.deposit = function (amount) {
  if (!Number.isInteger(amount) || amount <= 0) {
    throw new RangeError("deposit must be a positive integer of cents");
  }
  this.cents += amount;
  return this;
};

Wallet.prototype.withdraw = function (amount) {
  if (!Number.isInteger(amount) || amount <= 0) {
    throw new RangeError("withdrawal must be a positive integer of cents");
  }
  if (amount > this.cents) {
    throw new RangeError("insufficient funds");
  }
  this.cents -= amount;
  return this;
};

Wallet.prototype.balance = function () {
  return (this.cents / 100).toFixed(2);
};

Wallet.fromCents = function (owner, cents) {
  return new Wallet(owner, cents);
};

module.exports = { Wallet };

