const assert = require("node:assert");
const { Wallet } = require("./wallet");

// construction + chaining
const w = new Wallet("ada", 1000);
assert.strictEqual(w.owner, "ada");
assert.strictEqual(w.deposit(250).withdraw(750).balance(), "5.00");

// static factory stays on the constructor
const w2 = Wallet.fromCents("bob", 42);
assert.ok(w2 instanceof Wallet);
assert.strictEqual(w2.balance(), "0.42");

// error contract preserved
assert.throws(() => w.deposit(0), RangeError);
assert.throws(() => w.deposit(1.5), RangeError);
assert.throws(() => w.withdraw(999999), RangeError);
assert.throws(() => w.withdraw(-1), RangeError);

// balance formatting
assert.strictEqual(new Wallet("c", 5).balance(), "0.05");
assert.strictEqual(new Wallet("d", 0).balance(), "0.00");

console.log("PASS wallet behavior checks");

